using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using System.Xml;
using MC2Pack;
namespace Astera {
public sealed class ManagedGamePackage {public string Version="",Url="",Hash="",LauncherHash="",GameHash="";public long Bytes;}
public sealed class ManagedGameState {public string ProjectId="gacha-nebula-plus",Version="",ArchiveHash="";public Dictionary<string,string> Files=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);}
static class ManagedGames {
    internal const string Id="gacha-nebula-plus",Marker="Astera-game.json",Launcher="Gacha Nebula +.exe";
    internal static void Validate(ManagedGamePackage package){if(package==null||!Regex.IsMatch(package.Version??"","\\A[0-9]+\\.[0-9]+\\.[0-9]+(\\.[0-9]+)?\\z")||!Regex.IsMatch(package.Hash??"","\\A[0-9a-fA-F]{64}\\z")||package.Bytes<1||package.Bytes>2L*1024*1024*1024)throw new IOException("Invalid game release");if(!String.IsNullOrEmpty(package.Url))new Transport().Address(package.Url);foreach(string hash in new[]{package.LauncherHash,package.GameHash})if(!Regex.IsMatch(hash??"","\\A[0-9a-fA-F]{64}\\z"))throw new IOException("Game release is missing verified component hashes");}
    internal static string Relative(string path){path=path.Replace('\\','/').TrimEnd('/');if(path.Length==0||path.StartsWith("/")||path.Split('/').Any(p=>p.Length==0||p=="."||p==".."||p.EndsWith(".")||p.EndsWith(" ")||p.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(p,"\\A(con|prn|aux|nul|com[1-9]|lpt[1-9])(\\..*)?\\z",RegexOptions.IgnoreCase)))throw new IOException("Unsafe game archive path");return path;}
    internal static void NoLinks(string path){var current=new DirectoryInfo(Path.GetFullPath(path));while(current!=null){if(current.Exists&&(current.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Choose an installation folder outside junctions or symbolic links");current=current.Parent;}}
    internal static IEnumerable<string> Walk(string root){foreach(string entry in Directory.EnumerateFileSystemEntries(root)){if((File.GetAttributes(entry)&FileAttributes.ReparsePoint)!=0)throw new IOException("Installation contains a junction or symbolic link");if(Directory.Exists(entry)){foreach(string file in Walk(entry))yield return file;}else yield return entry;}}
    internal static ManagedGameState State(string root){string file=Path.Combine(root,Marker);if(!File.Exists(file))return null;if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0||new FileInfo(file).Length>4*1024*1024)throw new IOException("Invalid installation record");var state=Engine.Json.Deserialize<ManagedGameState>(File.ReadAllText(file));if(state==null||state.ProjectId!=Id||state.Files==null||state.Files.Count>10000)throw new IOException("This folder belongs to another installation");foreach(var path in state.Files.Keys)Relative(path);return state;}
    internal static string Install(string archive,ManagedGamePackage package,string root,CancellationToken stop,Action<string,long,long> progress,Func<bool> running=null,Action beforeCommit=null,Action beforeFinalMove=null){
        Validate(package);root=SelfUpdateFiles.Root(root);NoLinks(root);if(String.IsNullOrEmpty(Path.GetFileName(root)))throw new IOException("Choose a dedicated game folder");if(new FileInfo(archive).Length!=package.Bytes||!Engine.Hash(archive).Equals(package.Hash,StringComparison.OrdinalIgnoreCase))throw new IOException("The game ZIP does not match this verified release");
        string parent=Path.GetDirectoryName(root);Directory.CreateDirectory(parent);NoLinks(parent);string stage=Path.Combine(parent,".astera-nebula-stage-"+Guid.NewGuid().ToString("N")),backup=null;bool moved=false;
        using(var gate=new FileStream(root+".astera-install.lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None,4096,FileOptions.DeleteOnClose)){
            if(running!=null&&running())throw new IOException("Close Gacha Nebula + and its tray helper before updating");var old=Directory.Exists(root)?State(root):null;if(old!=null){Version current=Version.Parse(old.Version),wanted=Version.Parse(package.Version);if(wanted<current||wanted==current&&!old.ArchiveHash.Equals(package.Hash,StringComparison.OrdinalIgnoreCase))throw new IOException("This release is older or changed without a version increase");}if(Directory.Exists(root)&&old==null&&Directory.EnumerateFileSystemEntries(root).Any())throw new IOException("Choose a new empty folder; existing unmanaged files were left alone");
            Directory.CreateDirectory(stage);try{
                var next=new ManagedGameState{Version=package.Version,ArchiveHash=package.Hash};
                using(var zip=ZipFile.OpenRead(archive)){
                    if(zip.Entries.Count<1||zip.Entries.Count>10000)throw new IOException("Unsupported archive entry count");var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;
                    foreach(var entry in zip.Entries){string name=Relative(entry.FullName);if(!paths.Add(name)||(((entry.ExternalAttributes>>16)&0xf000)==0xa000||(entry.ExternalAttributes&0x400)!=0))throw new IOException("Duplicate path or symbolic link in game archive");if(entry.Length>1024L*1024*1024||(total+=entry.Length)>4L*1024*1024*1024)throw new IOException("Game archive exceeds extraction limits");if(name.Equals(Marker,StringComparison.OrdinalIgnoreCase)||name.Equals("Recovery",StringComparison.OrdinalIgnoreCase)||name.StartsWith("Recovery/",StringComparison.OrdinalIgnoreCase)||name.EndsWith(".sol",StringComparison.OrdinalIgnoreCase))throw new IOException("The package must not contain player saves or recovery backups");}
                    long done=0;foreach(var entry in zip.Entries){stop.ThrowIfCancellationRequested();string name=Relative(entry.FullName),destination=SelfUpdateFiles.Inside(stage,name);if(entry.FullName.EndsWith("/")||entry.FullName.EndsWith("\\")){Directory.CreateDirectory(destination);continue;}Directory.CreateDirectory(Path.GetDirectoryName(destination));using(var input=entry.Open())using(var output=new FileStream(destination,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var buffer=new byte[65536];int read;while((read=input.Read(buffer,0,buffer.Length))>0){stop.ThrowIfCancellationRequested();output.Write(buffer,0,read);done+=read;if(done>total)throw new IOException("Archive extracted more data than declared");if(progress!=null)progress("Installing Gacha Nebula +",done,total);}}next.Files.Add(name,Engine.Hash(destination));}
                }
                CustomGames.Validate(Path.Combine(stage,Launcher));if(!Engine.Hash(Path.Combine(stage,Launcher)).Equals(package.LauncherHash,StringComparison.OrdinalIgnoreCase)||!Engine.Hash(Path.Combine(stage,"game","GachaNebula.swf")).Equals(package.GameHash,StringComparison.OrdinalIgnoreCase))throw new IOException("The game or helper does not match the verified release");
                string descriptor=Path.Combine(stage,"game","META-INF","AIR","application.xml");bool identity=false;using(var reader=XmlReader.Create(descriptor,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null})){while(reader.Read())if(reader.NodeType==XmlNodeType.Element&&reader.LocalName=="id"){identity=reader.ReadElementContentAsString()=="com.starsallies.nebula.stability";break;}}if(!identity)throw new IOException("Unexpected game save-profile identity");
                if(Directory.Exists(root))foreach(string file in Walk(root)){stop.ThrowIfCancellationRequested();string relative=Relative(file.Substring(root.Length).TrimStart(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar));if(relative==Marker||old!=null&&old.Files.Keys.Any(p=>p.Equals(relative,StringComparison.OrdinalIgnoreCase)))continue;if(next.Files.ContainsKey(relative)){if(!Engine.Hash(file).Equals(next.Files[relative],StringComparison.OrdinalIgnoreCase))throw new IOException("A personal file conflicts with the update: "+relative);continue;}string to=SelfUpdateFiles.Inside(stage,relative);Directory.CreateDirectory(Path.GetDirectoryName(to));File.Copy(file,to);}
                File.WriteAllText(Path.Combine(stage,Marker),Engine.Json.Serialize(next));stop.ThrowIfCancellationRequested();if(beforeCommit!=null)beforeCommit();NoLinks(root);if(running!=null&&running())throw new IOException("The game started during preparation; installation was stopped");
                if(Directory.Exists(root)){backup=root+".astera-backup-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8);Directory.Move(root,backup);moved=true;}
                try{if(beforeFinalMove!=null)beforeFinalMove();Directory.Move(stage,root);}catch{if(moved&&!Directory.Exists(root))Directory.Move(backup,root);throw;}return Path.Combine(root,Launcher);
            }finally{if(Directory.Exists(stage)){NoLinks(stage);Walk(stage).ToArray();string exact=Path.GetFullPath(stage);if(Path.GetDirectoryName(exact)!=Path.GetFullPath(parent)||!Path.GetFileName(exact).StartsWith(".astera-nebula-stage-",StringComparison.Ordinal))throw new IOException("Unsafe temporary cleanup path");Directory.Delete(exact,true);}}
        }
    }
}
}
